16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "membership_tier")
66	    private String membershipTier;
67	
68	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
69	    private Set<Pet> pets;
70	
71	    public String getAddress() {
72	        return this.address;
73	    }
74	
75	    public void setAddress(String address) {
76	        this.address = address;
77	    }
78	
79	    public String getCity() {
80	        return this.city;
81	    }
82	
83	    public void setCity(String city) {
84	        this.city = city;
85	    }
86	
87	    public String getTelephone() {
88	        return this.telephone;
89	    }
90	
91	    /**
92	     * Store the telephone number as digits only, stripping any spaces, dashes
93	     * and parentheses so that, e.g., "(613) 555-0100" and "6135550100" are kept
94	     * as the same value.
95	     */
96	    public void setTelephone(String telephone) {
97	        this.telephone = telephone == null ? null : telephone.replaceAll("[^0-9]", "");
98	    }
99	
100	    public String getEmail() {
101	        return this.email;
102	    }
103	
104	    public void setEmail(String email) {
105	        this.email = email;
106	    }
107	
108	    public LocalDate getRegistrationDate() {
109	        return this.registrationDate;
110	    }
111	
112	    public void setRegistrationDate(LocalDate registrationDate) {
113	        this.registrationDate = registrationDate;
114	    }
115	
116	    public Integer getMembershipNumber() {
117	        return this.membershipNumber;
118	    }
119	
120	    public void setMembershipNumber(Integer membershipNumber) {
121	        this.membershipNumber = membershipNumber;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    public String getMembershipTier() {
133	        return this.membershipTier;
134	    }
135	
136	    public void setMembershipTier(String membershipTier) {
137	        this.membershipTier = membershipTier;
138	    }
139	
140	    /**
141	     * The owner's display name, formatted as 'LastName, FirstName'.
142	     */
143	    @Transient
144	    public String getDisplayName() {
145	        return this.getLastName() + ", " + this.getFirstName();
146	    }
147	
148	    /**
149	     * The owner's initials: the upper-cased first letters of the first and last
150	     * name, dot-separated with a trailing dot, e.g. 'J.S.'.
151	     */
152	    @Transient
153	    public String getInitials() {
154	        return (this.getFirstName().substring(0, 1) + "." + this.getLastName().substring(0, 1) + ".")
155	            .toUpperCase();
156	    }
157	
158	    protected Set<Pet> getPetsInternal() {
159	        if (this.pets == null) {
160	            this.pets = new HashSet<>();
161	        }
162	        return this.pets;
163	    }
164	
165	    protected void setPetsInternal(Set<Pet> pets) {
166	        this.pets = pets;
167	    }
168	
169	    public List<Pet> getPets() {
170	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
171	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
172	        return Collections.unmodifiableList(sortedPets);
173	    }
174	
175	    public void setPets(List<Pet> pets) {
176	        this.pets = new HashSet<>(pets);
177	    }
178	
179	    public void addPet(Pet pet) {
180	        getPetsInternal().add(pet);
181	        pet.setOwner(this);
182	    }
183	
184	    /**
185	     * Return the Pet with the given name, or null if none found for this Owner.
186	     *
187	     * @param name to test
188	     * @return true if pet name is already in use
189	     */
190	    public Pet getPet(String name) {
191	        return getPet(name, false);
192	    }
193	
194	    /**
195	     * Return the Pet with the given name, or null if none found for this Owner.
196	     *
197	     * @param name to test
198	     * @return true if pet name is already in use
199	     */
200	    public Pet getPet(String name, boolean ignoreNew) {
201	        name = name.toLowerCase();
202	        for (Pet pet : getPetsInternal()) {
203	            if (!ignoreNew || !pet.isNew()) {
204	                String compName = pet.getName();
205	                compName = compName.toLowerCase();
206	                if (compName.equals(name)) {
207	                    return pet;
208	                }
209	            }
210	        }
211	        return null;
212	    }
213	
214	    public Pet getPet(Integer petId) {
215	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
216	    }
217	
218	    @Override
219	    public String toString() {
220	        return new ToStringCreator(this)
221	
222	            .append("id", this.getId())
223	            .append("new", this.isNew())
224	            .append("lastName", this.getLastName())
225	            .append("firstName", this.getFirstName())
226	            .append("address", this.address)
227	            .append("city", this.city)
228	            .append("telephone", this.telephone)
229	            .append("email", this.email)
230	            .toString();
231	    }
232	}
